use super::*;
use semio_framework_value::{ErasedSnapshotRetirement,FactoryAuthority,FactoryRetirement,factory::OwnedValueRetirementFactory};
use semio_framework_value::retained_clone::{RetainedCloneClose,RetainedOwnedProjection};
fn grant(demand:RetirementDemand)->RetainedCloneGrant {RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth}}
fn observed<T>(call:impl FnOnce()->T)->(T,usize,usize){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(call);assert!(!heap.overflowed);(value,heap.requested_bytes,heap.released_bytes)}
fn receipt(progress:RetainedCloneProgress,grant:RetainedCloneGrant,allocated:usize,released:usize){assert!(progress.fits(grant));assert!(allocated<=progress.retained_capacity_bytes);assert!(released<=progress.released_bytes);}
fn close_projection<T:?Sized+Sync>(projection:&mut RetainedOwnedProjection<T>){let mut work=0;for _ in 0..10000 {if projection.terminal_is_empty(){assert!(work>0);return;}let funded=grant(projection.close_demand(4096).unwrap());let(turn,allocated,released)=observed(||projection.close_step(funded));work+=turn.work;receipt(turn.result.unwrap().progress(),funded,allocated,released);}panic!("original operation projection did not close");}
fn close_factory(factory:Arc<dyn ArtifactOwnedValueRetirementFactory<Vec<String>>>){let factory:Arc<dyn FactoryRetirement>=factory;let mut owner=FactoryAuthority::new(factory);let mut work=0;for _ in 0..10000 {if owner.terminal_is_empty(){assert!(work>0);return;}let funded=grant(owner.demands(4096).unwrap());let(turn,allocated,released)=observed(||owner.step(funded));work+=turn.work;receipt(turn.result.unwrap().progress(),funded,allocated,released);}panic!("captured original history issuer did not close");}
fn close_value<T:semio_framework_value::retirement::RetireOwned>(value:T){let mut original=Some(value);let mut close=RetainedCloneClose::default();let mut work=0;for _ in 0..10000 {if original.is_none()&&close.is_empty(){assert!(work>0);return;}let mut funded=grant(close.next_owner_demands::<T>(original.is_some(),&None,4096).unwrap());funded.maximum_copy_bytes=4096;let(turn,allocated,released)=observed(||{let first=close.begin_granted(&mut original,funded);match first.result{Ok(Some(step))=>semio_framework_value::RetainedWorkOutcome{result:Ok(step),work:first.work},Ok(None)=>{let next=close.step_granted(funded);semio_framework_value::RetainedWorkOutcome{result:next.result,work:first.work+next.work}},Err(error)=>semio_framework_value::RetainedWorkOutcome{result:Err(error),work:first.work}}});work+=turn.work;receipt(turn.result.unwrap().progress(),funded,allocated,released);}panic!("original history value {} did not close: {:?}",std::any::type_name::<T>(),close.next_owner_demands::<T>(original.is_some(),&None,4096));}
fn close_ledger(ledger:&mut ArtifactHistoryLedger<Vec<String>>){while let Some(original)=ledger.pop(){close_value(original);}while ledger.retained_terminal_slot_count()>0{let funded=RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()};let(visibility,progress)=ledger.retire_terminal_slot(funded).unwrap();if let Some(visibility)=visibility{close_value(semio_framework_value::retirement::arc_custody::SharedControlledRetirement::lease(visibility));}assert!(progress.fits(funded));}while !ledger.backing_is_empty(){let funded=RetainedCloneGrant{maximum_items:1,maximum_release_bytes:ledger.next_empty_page_release_byte_demand().unwrap(),maximum_depth:1,..Default::default()};let(step,allocated,released)=observed(||ledger.release_empty_page(funded).unwrap());receipt(step.progress(),funded,allocated,released);}}
fn return_original(ledger:&mut ArtifactHistoryLedger<Vec<String>>,key:ArtifactHistoryReadKey){let mut returned=None;for _ in 0..10000 {let funded=grant(ledger.retained_read_return_demands(key,4096).unwrap());let(step,allocated,released)=observed(||witness(ledger.return_retained_read(key,&mut returned,funded)).unwrap());receipt(step.progress(),funded,allocated,released);if matches!(step,RetainedCloneStep::Complete(_)){if let Some(factory)=returned.take(){close_factory(factory);}return;}}panic!("same original history slot did not return");}
fn witness<T>(turn:semio_framework_value::RetainedWorkOutcome<T>)->Result<T,ValueError>{HISTORY_TEST_WORK.fetch_add(turn.work,std::sync::atomic::Ordering::Relaxed);turn.result}
static HISTORY_TEST_WORK:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);
fn corpus()->serde_json::Value {serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../../🔗️read/🧪️tests/🧫️fixtures/🔣️.json")).unwrap()}
#[test]
fn original_history_read_work_preserves_actual_source_and_alias_receipts(){
 let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<Vec<String>>>=Arc::new(OwnedValueRetirementFactory::<Vec<String>>::default());let mut ledger=ArtifactHistoryLedger::new();let slot=ledger.try_push(vec!["original".to_owned()]).unwrap();let key=ledger.retained_read_key(slot).unwrap();let demand=ledger.retained_read_demands(key).unwrap();let denied=ledger.advance_retained_read(key,&factory,RetainedCloneGrant{maximum_items:0,..grant(demand)});assert_eq!(denied.work,0);assert_eq!(denied.result.unwrap().progress(),Default::default());let mut work=0;for _ in 0..10{let demand=ledger.retained_read_demands(key).unwrap();let turn=ledger.advance_retained_read(key,&factory,grant(demand));work+=turn.work;if matches!(turn.result.unwrap(),RetainedCloneStep::Complete(_)){break}}assert!(work>0);let turn=ledger.retain_read(key,grant(RetainedOwnedProjection::<Vec<String>>::constructor_demand()));assert!(turn.work>0);let(mut projection,_)=turn.result.unwrap();assert_eq!(projection.borrow().unwrap().get()[0],"original");close_projection(&mut projection);let mut returned=None;let mut returned_work=0;for _ in 0..1000{let demand=ledger.retained_read_return_demands(key,4096).unwrap();let turn=ledger.return_retained_read(key,&mut returned,grant(demand));returned_work+=turn.work;if matches!(turn.result.unwrap(),RetainedCloneStep::Complete(_)){break}}assert!(returned_work>0);close_factory(returned.take().unwrap());close_ledger(&mut ledger);close_factory(factory);
}
#[test]
fn original_history_reads_keep_forward_backing_and_refuse_each_denied_currency(){
 let corpus=corpus();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<Vec<String>>>=Arc::new(OwnedValueRetirementFactory::<Vec<String>>::default());let mut count=0;
 for case in corpus["cases"].as_array().unwrap(){
  let original:Vec<String>=case["operations"].as_array().unwrap().iter().map(|op|serde_json::to_string(op).unwrap()).collect();let pointer=original.as_ptr();let mut ledger=ArtifactHistoryLedger::new();let slot=ledger.try_push(original).unwrap();let key=ledger.retained_read_key_at(0).unwrap();assert!(ledger.retained_read(key).is_err());
  for _ in 0..10 {
   let demand=ledger.retained_read_demands(key).unwrap();let funded=grant(demand);
   for axis in 0..5 {let mut denied=funded;match axis {0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if demand.release_bytes>0=>denied.maximum_release_bytes-=1,4 if demand.depth>0=>denied.maximum_depth-=1,_=>continue};let(step,allocated,released)=observed(||witness(ledger.advance_retained_read(key,&factory,denied)).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!((allocated,released),(0,0));assert_eq!(ledger.get_key(slot).unwrap().as_ptr(),pointer);assert_eq!(ledger.retained_read_demands(key).unwrap(),demand);}
   let(step,allocated,released)=observed(||witness(ledger.advance_retained_read(key,&factory,funded)).unwrap());receipt(step.progress(),funded,allocated,released);if matches!(step,RetainedCloneStep::Complete(_)){break;}
  }
  let funded=grant(RetainedOwnedProjection::<Vec<String>>::constructor_demand());let((mut root,progress),allocated,released)=observed(||witness(ledger.retain_read(key,funded)).unwrap());receipt(progress,funded,allocated,released);
  let mut projections=Vec::new();for index in case["readOrder"].as_array().unwrap(){let index=index.as_u64().unwrap() as usize;let original_pointer=ledger.get_key(slot).unwrap()[index].as_ptr();let funded=grant(RetainedOwnedProjection::<String>::constructor_demand());let((projection,progress),allocated,released)=observed(||witness(root.project(index+1,|ops|&ops[index],funded)).unwrap());receipt(progress,funded,allocated,released);assert_eq!(projection.borrow().unwrap().get().as_ptr(),original_pointer);projections.push(projection);}
  assert!(ledger.get_mut(0).is_none());assert!(ledger.remove_key(slot).is_err());assert_eq!(ledger.iter().count(),1);assert_eq!(ledger.first().unwrap().as_ptr(),pointer);
  if !projections.is_empty(){let mut returned=None;let mut blocked=false;for _ in 0..1000 {let funded=grant(ledger.retained_read_return_demands(key,4096).unwrap());let(result,allocated,released)=observed(||witness(ledger.return_retained_read(key,&mut returned,funded)));match result {Ok(step)=>{receipt(step.progress(),funded,allocated,released);assert!(!matches!(step,RetainedCloneStep::Complete(_)));},Err(error)=>{assert_eq!(error.kind,ValueRefusalKind::WorkLimit);assert_eq!((allocated,released),(0,0));blocked=true;break;}}}assert!(blocked);assert!(returned.is_none());}
   for projection in &mut projections {close_projection(projection);}close_projection(&mut root);return_original(&mut ledger,key);assert_eq!(ledger.get_key(slot).unwrap().as_ptr(),pointer);assert!(ledger.get_mut(0).is_some());close_ledger(&mut ledger);count+=1;
 }
 close_factory(factory);
}
#[test]
fn original_history_reads_return_every_cancelled_birth_and_reject_foreign_generations(){
 let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<Vec<String>>>=Arc::new(OwnedValueRetirementFactory::<Vec<String>>::default());
 for cutoff in 0..4 {let original=vec!["original-operation".repeat(1024)];let pointer=original[0].as_ptr();let mut ledger=ArtifactHistoryLedger::new();let slot=ledger.try_push(original).unwrap();let key=ledger.retained_read_key_at(0).unwrap();let mut foreign=ArtifactHistoryLedger::<Vec<String>>::new();foreign.try_push(vec![]).unwrap();assert!(foreign.retained_read_demands(key).is_err());close_ledger(&mut foreign);
  for _ in 0..cutoff {let funded=grant(ledger.retained_read_demands(key).unwrap());let(step,allocated,released)=observed(||witness(ledger.advance_retained_read(key,&factory,funded)).unwrap());receipt(step.progress(),funded,allocated,released);if matches!(step,RetainedCloneStep::Complete(_)){break;}}
  if cutoff>0 {return_original(&mut ledger,key);}assert_eq!(ledger.get_key(slot).unwrap()[0].as_ptr(),pointer);let original=ledger.remove_key(slot).unwrap();close_value(original);ledger.try_push(vec![]).unwrap();assert!(ledger.retained_read_demands(key).is_err());close_ledger(&mut ledger);
 }
 close_factory(factory);
}

#[test]
fn original_history_reads_refuse_unpublished_groups_and_foreign_original_issuers(){
 let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<Vec<String>>>=Arc::new(OwnedValueRetirementFactory::<Vec<String>>::default());
  let wrong:Arc<dyn ArtifactOwnedValueRetirementFactory<Vec<String>>>=Arc::new(OwnedValueRetirementFactory::<Vec<String>>::default());
 let mut ledger=ArtifactHistoryLedger::new();let mut group=super::super::ArtifactGroupVisibilityOwner::new();let visibility=group.view();let reservation=ledger.reserve_group_one(&visibility).unwrap();let slot=ledger.stage_group_reserved(reservation,vec!["actual-original".repeat(1024)],&visibility).unwrap();let key=ArtifactHistoryReadKey{authority:ledger.authority(),issuance:ledger.retained_issuance(),key:slot};
 assert!(ledger.retained_read_key_at(0).is_none());let(result,allocated,released)=observed(||ledger.retained_read_demands(key));assert!(result.is_err());assert_eq!((allocated,released),(0,0));assert!(group.commit());ledger.adopt_group(&visibility).unwrap();let key=ledger.retained_read_key_at(0).unwrap();
 for _ in 0..10 {let funded=grant(ledger.retained_read_demands(key).unwrap());let(step,allocated,released)=observed(||witness(ledger.advance_retained_read(key,&factory,funded)).unwrap());receipt(step.progress(),funded,allocated,released);if matches!(step,RetainedCloneStep::Complete(_)){break;}}
 let funded=grant(ledger.retained_read_demands(key).unwrap());let(result,allocated,released)=observed(||witness(ledger.advance_retained_read(key,&wrong,funded)));assert!(result.is_err());assert_eq!((allocated,released),(0,0));return_original(&mut ledger,key);close_ledger(&mut ledger);drop(group);close_value(visibility);close_factory(wrong);close_factory(factory);
}

struct OpaqueProjectedBytes {bytes:Vec<u8>}
struct OriginalProjectedAuthority {original:OpaqueProjectedBytes}
impl semio_framework_value::retirement::RetireOwned for OriginalProjectedAuthority {
 fn retirement(self)->Box<dyn semio_framework_value::retirement::RetirementCursor>{semio_framework_value::retirement::RetireOwned::retirement(self.original.bytes)}
 fn retirement_birth_bytes(&self)->Option<usize>{semio_framework_value::retirement::RetireOwned::retirement_birth_bytes(&self.original.bytes)}
 fn controlled_retirement_supported()->bool{true}
}
#[test]
fn original_projected_source_requires_retirement_only_from_its_actual_authority(){
 let corpus:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../../🔗️read/🧪️tests/🧫️fixtures/🔗️projection.json")).unwrap();
 for case in corpus["cases"].as_array().unwrap(){
  let bytes:Vec<u8>=case["bytes"].as_array().unwrap().iter().map(|byte|byte.as_u64().unwrap() as u8).collect();let pointer=bytes.as_ptr();let authority=OriginalProjectedAuthority{original:OpaqueProjectedBytes{bytes}};
  let mut admission_work=0;let mut admission=semio_framework_value::retained_clone::RetainedCloneSourceAdmission::new(authority,(),|original:&OriginalProjectedAuthority|&original.original);let mut output=None;
  for _ in 0..100 {if admission.phase()=="ready"{break}let demand=admission.next_demand().unwrap();let funded=grant(demand);let mut denied=funded;denied.maximum_items=0;let(turn,allocated,released)=observed(||admission.advance(denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!((allocated,released),(0,0));assert_eq!(admission.original_authority().unwrap().original.bytes.as_ptr(),pointer);let(turn,allocated,released)=observed(||admission.advance(funded));admission_work+=turn.work;receipt(turn.result.unwrap().progress(),funded,allocated,released);}
  assert_eq!(admission.phase(),"ready");let funded=grant(RetirementDemand{depth:1,..Default::default()});let(turn,allocated,released)=observed(||admission.take_output(&mut output,funded));admission_work+=turn.work;assert!(admission_work>0);receipt(turn.result.unwrap().progress(),funded,allocated,released);let mut source=output.unwrap();assert_eq!(source.borrow().get().bytes.as_ptr(),pointer);assert_eq!(serde_json::to_value(&source.borrow().get().bytes).unwrap(),case["expected"]);
   let mut finished=false;let mut work=0;for _ in 0..10000{if source.terminal_is_empty(){finished=true;break;}let funded=grant(source.next_close_demand(4096).unwrap());let(turn,allocated,released)=observed(||source.close_step(funded));work+=turn.work;receipt(turn.result.unwrap().progress(),funded,allocated,released);}assert!(finished);assert!(work>0);
 }
}
#[test]
fn original_history_reverse_links_borrow_the_same_generation_without_heap_work(){
 let law:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../../../🔗️read/🧪️tests/🧫️fixtures/⏮️links.json")).unwrap();let mut ledger=ArtifactHistoryLedger::new();let mut keys=Vec::new();let mut pointers=Vec::new();for row in law["rows"].as_array().unwrap(){let original=row.as_array().unwrap().iter().map(|value|value.as_str().unwrap().to_owned()).collect::<Vec<_>>();pointers.push(original.as_ptr());keys.push(ledger.try_push(original).unwrap());}
 let(mut cursor,allocated,released)=observed(||ledger.last_key());assert_eq!((allocated,released),(0,0));for expected in law["expected"].as_array().unwrap(){let index=expected.as_u64().unwrap()as usize;let key=cursor.unwrap();assert_eq!(key,keys[index]);let((pointer,previous),allocated,released)=observed(||(ledger.get_key(key).unwrap().as_ptr(),ledger.previous_key(key)));assert_eq!(pointer,pointers[index]);assert_eq!((allocated,released),(0,0));cursor=previous;}assert!(cursor.is_none());let stale=keys[1];close_value(ledger.remove_key(stale).unwrap());assert!(ledger.previous_key(stale).is_none());assert_eq!(ledger.previous_key(keys[2]),Some(keys[0]));close_ledger(&mut ledger);assert!(ledger.last_key().is_none());
}
